    is_sorted([1, 2, 2, 3, 3, 4]) ➞ True
    is_sorted([1, 2, 2, 2, 3, 4]) ➞ False
    '''
    if len(lst) <= 1:
        return True

    count = {}
    for num in lst:
        if num in count:
            count[num] += 1
            if count[num] > 1:
                return False
        else:
            count[num] = 1

    return all(lst[i] <= lst[i + 1] for i in range(len(lst) - 1))

