import math


def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])


def find_zero(xs: list):
    """ xs are coefficients of a polynomial.
    find_zero find x such that poly(x) = 0.
    find_zero returns only one zero point, even if there are many.
    Moreover, find_zero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> round(find_zero([1, 2]), 2) # f(x) = 1 + 2x
    -0.5
    >>> round(find_zero([-6, 11, -6, 1]), 2) # (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
    """
    if len(xs) % 2 != 0 or xs[-1] == 0:
        raise ValueError("List must have an even number of coefficients and the largest non-zero coefficient must be non-zero.")

    # Use the Rational Root Theorem to find possible rational roots
    possible_roots = []
    for i in range(1, abs(xs[-1]) + 1):
        if xs[-1] % i == 0:
            possible_roots.append(i)
            possible_roots.append(-i)

    # Check each possible root
    for root in possible_roots:
        if poly(xs, root) == 0:
            return root

    # If no rational root is found, use a numerical method like Newton's method
    def f(x):
        return poly(xs, x)

    def df(x):
        return sum([i * coeff * math.pow(x, i - 1) for i, coeff in enumerate(xs) if i > 0])

    x = 0  # Initial guess
    for _ in range(100):  # Maximum 100 iterations
        x_new = x - f(x) / df(x)
        if abs(x_new - x) < 1e-6:
            return round(x_new, 2)
        x = x_new

    raise ValueError("No root found within the maximum number of iterations.")
